-- ---------- 3) SHEN-SHU-E: anatomy_en ให้ตรงกับภาษาไทย (เจ้าของยืนยัน 1 cun) ----------
update points set anatomy_en = 'Dorsolateral lumbosacral region, 1 cun lateral to BAI-HUI'
where code = 'SHEN-SHU-E'
  and anatomy_en = 'Dorsolateral lumbosacral region, 1.5 cun lateral to Bai-hui';

